const WebSocket = require('ws');
const http = require('http');
const crypto = require('crypto');
const url = require('url');

const SESSION_STORE = new Map();
const RATE_LIMITS = new Map();
const PENDING_UPGRADES = new Map();

const MAX_REQUESTS_PER_WINDOW = 20;
const WINDOW_MS = 60000;
const RETRY_DELAY_BASE = 1000;
const MAX_RETRIES = 3;
const SESSION_MAX_AGE_MS = 24 * 60 * 60 * 1000; // 24 hours

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

function createSession(userId) {
  const token = generateToken();
  SESSION_STORE.set(token, { userId, createdAt: Date.now(), verified: true });
  return token;
}

function checkRateLimit(clientId) {
  const now = Date.now();
  let record = RATE_LIMITS.get(clientId);
  if (!record || (now - record.windowStart) > WINDOW_MS) {
    record = { windowStart: now, count: 0 };
    RATE_LIMITS.set(clientId, record);
  }
  record.count++;
  return record.count <= MAX_REQUESTS_PER_WINDOW;
}

function extractOrigin(req) {
  return req.headers['origin'] || req.headers['sec-websocket-origin'] || null;
}

function validateOrigin(origin, allowedOrigins) {
  if (!origin) return false;
  return allowedOrigins.some(allowed => origin.toLowerCase() === allowed.toLowerCase());
}

function getSessionFromRequest(req) {
  const parsedUrl = url.parse(req.url, true);
  const token = parsedUrl.query.token;
  if (!token) return null;
  const session = SESSION_STORE.get(token);
  if (!session) return null;
  // Enforce session expiration to prevent indefinitely valid tokens (CWE-613).
  if ((Date.now() - session.createdAt) > SESSION_MAX_AGE_MS) {
    SESSION_STORE.delete(token);
    return null;
  }
  return session;
}

function deriveClientId(req) {
  const forwarded = req.headers['x-forwarded-for'];
  const ip = forwarded ? forwarded.split(',')[0].trim() : req.socket.remoteAddress;
  return ip;
}

class SecureWebSocketServer {
  constructor(options = {}) {
    this.allowedOrigins = options.allowedOrigins || ['https://app.example.com'];
    this.server = http.createServer(this.handleHTTP.bind(this));
    this.wss = new WebSocket.Server({ noServer: true });
    this.retryState = new Map();

    this.server.on('upgrade', this.handleUpgrade.bind(this));
    this.wss.on('connection', this.handleConnection.bind(this));
  }

  handleHTTP(req, res) {
    if (req.url === '/health') {
      res.writeHead(200);
      res.end('OK');
      return;
    }
    res.writeHead(404);
    res.end();
  }

  handleUpgrade(req, socket, head) {
    const clientId = deriveClientId(req);

    if (!checkRateLimit(clientId)) {
      const retryInfo = this.getRetryInfo(clientId);
      if (retryInfo.attempts < MAX_RETRIES) {
        retryInfo.attempts++;
        const delay = RETRY_DELAY_BASE * Math.pow(2, retryInfo.attempts - 1);
        PENDING_UPGRADES.set(clientId, { req, socket, head, timestamp: Date.now() });
        setTimeout(() => this.retryUpgrade(clientId), delay);
        return;
      }
      socket.write('HTTP/1.1 429 Too Many Requests\r\n\r\n');
      socket.destroy();
      return;
    }

    this.performUpgrade(req, socket, head);
  }

  getRetryInfo(clientId) {
    if (!this.retryState.has(clientId)) {
      this.retryState.set(clientId, { attempts: 0, lastAttempt: Date.now() });
    }
    return this.retryState.get(clientId);
  }

  retryUpgrade(clientId) {
    const pending = PENDING_UPGRADES.get(clientId);
    if (!pending) return;
    PENDING_UPGRADES.delete(clientId);

    if (checkRateLimit(clientId)) {
      this.performUpgrade(pending.req, pending.socket, pending.head);
    } else {
      pending.socket.write('HTTP/1.1 429 Too Many Requests\r\n\r\n');
      pending.socket.destroy();
    }
  }

  performUpgrade(req, socket, head) {
    const origin = extractOrigin(req);
    const session = getSessionFromRequest(req);

    const originValid = this.validateUpgradeOrigin(origin);
    const sessionValid = session && session.verified;

    if (originValid && sessionValid) {
      this.wss.handleUpgrade(req, socket, head, (ws) => {
        ws.userSession = session;
        this.wss.emit('connection', ws, req);
      });
    } else {
      socket.write('HTTP/1.1 403 Forbidden\r\n\r\n');
      socket.destroy();
    }
  }

  validateUpgradeOrigin(origin) {
    return validateOrigin(origin, this.allowedOrigins);
  }

  handleConnection(ws, req) {
    const clientId = deriveClientId(req);

    ws.on('message', (data) => {
      if (!checkRateLimit(clientId)) {
        ws.send(JSON.stringify({ error: 'rate_limited', retryAfter: WINDOW_MS / 1000 }));
        return;
      }
      try {
        const msg = JSON.parse(data);
        this.processMessage(ws, msg);
      } catch (e) {
        ws.send(JSON.stringify({ error: 'invalid_message' }));
      }
    });

    ws.on('close', () => {
      this.retryState.delete(clientId);
    });
  }

  processMessage(ws, msg) {
    if (msg.type === 'ping') {
      ws.send(JSON.stringify({ type: 'pong', timestamp: Date.now() }));
    } else if (msg.type === 'subscribe') {
      ws.send(JSON.stringify({ type: 'subscribed', channel: msg.channel }));
    }
  }

  listen(port) {
    this.server.listen(port, () => {
      console.log(`WebSocket server listening on port ${port}`);
    });
  }
}

const server = new SecureWebSocketServer({
  allowedOrigins: ['https://app.example.com', 'https://admin.example.com']
});

server.listen(8080);

module.exports = { SecureWebSocketServer, createSession };
